<script setup lang="ts">
useSeoMeta({ title: 'Admin – Bunker Club', robots:'noindex, nofollow' })
const password=ref(''), loggedIn=ref(false), error=ref(''), inquiries=ref<any[]>([]), conversations=ref<any[]>([]), selected=ref(''), messages=ref<any[]>([]), reply=ref(''), tab=ref<'inquiries'|'chat'>('inquiries')
async function load() { try { inquiries.value=await $fetch<any[]>('/api/admin/inquiries'); conversations.value=await $fetch<any[]>('/api/admin/conversations'); loggedIn.value=true } catch { loggedIn.value=false } }
onMounted(load)
async function login(){ error.value=''; try { await $fetch('/api/admin/login',{method:'POST',body:{password:password.value}}); password.value=''; await load(); if (!loggedIn.value) error.value='Unable to load the database.' } catch { error.value='Login failed. Check credentials and configuration.' } }
async function logout(){ await $fetch('/api/admin/logout',{method:'POST'}); loggedIn.value=false; inquiries.value=[]; messages.value=[] }
async function select(id:string){selected.value=id; messages.value=await $fetch<any[]>('/api/admin/messages',{query:{conversation:id}})}
async function send(){if(!reply.value.trim())return; try {await $fetch('/api/admin/messages',{method:'POST',body:{conversation:selected.value,message:reply.value}}); reply.value=''; await select(selected.value)} catch {error.value='Unable to send reply.'} }
</script>
<template><section class="wrap page admin"><template v-if="!loggedIn"><h1>Admin</h1><form class="form login" @submit.prevent="login"><label>Password<input v-model="password" type="password" required autocomplete="current-password"></label><p v-if="error" class="error">{{ error }}</p><button class="button dark">SIGN IN</button></form></template><template v-else><div class="section-heading"><h1>Dashboard</h1><button @click="logout">Sign out</button></div><div class="admin-tabs"><button @click="tab='inquiries';load()">Inquiries</button><button @click="tab='chat';load()">Chat</button><button @click="load()">Refresh</button></div><div v-if="tab==='inquiries'" class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Name</th><th>Contact</th><th>Model</th><th>Message</th></tr></thead><tbody><tr v-for="i in inquiries" :key="i.id"><td>{{ new Date(i.created_at).toLocaleString() }}</td><td>{{ i.kind }}</td><td>{{ i.name }}</td><td>{{ i.email }}<br>{{ i.phone }}</td><td>{{ i.model }}</td><td>{{ i.message }}</td></tr></tbody></table><p v-if="!inquiries.length">No inquiries yet.</p></div><div v-else class="admin-chat"><div><h2>Conversations</h2><button v-for="c in conversations" :key="c.conversation" class="conversation" @click="select(c.conversation)">{{ c.conversation.slice(0,12) }} · {{ c.message_count }} messages</button><p v-if="!conversations.length">No conversations yet.</p></div><div v-if="selected"><h2>Messages</h2><div class="admin-messages"><p v-for="m in messages" :key="m.id"><strong>{{ m.sender }}:</strong> {{ m.message }}</p></div><form class="form" @submit.prevent="send"><label>Reply<textarea v-model="reply" required maxlength="2000" rows="3"></textarea></label><button class="button dark">SEND REPLY</button></form></div></div><p v-if="error" class="error">{{ error }}</p></template></section></template>
